cd numchart && cat > inputs/data.schema.json <<'EOF'
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Data",
  "description": "A list of numbers to chart, in order, with a title.",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "values"],
  "properties": {
    "title": {
      "type": "string",
      "minLength": 1,
      "maxLength": 200,
      "title": "Title",
      "description": "The heading of the page; it names what the numbers measure."
    },
    "unit": {
      "type": "string",
      "minLength": 1,
      "maxLength": 20,
      "title": "Unit",
      "description": "What one number counts, such as \"ms\" or \"orders\". Shown in the tooltip and table header."
    },
    "values": {
      "type": "array",
      "minItems": 1,
      "maxItems": 5000,
      "title": "Values",
      "description": "The numbers to chart, in the order they are plotted from left to right.",
      "items": { "type": "number" }
    }
  }
}
EOF
cat > inputs/data.md <<'EOF'
# Data

- **title** is the page heading and names what the numbers measure.
- **unit** (optional) is what one number counts, such as `ms` or `orders`.
  It appears in the tooltip and the table header.
- **values** is the list of numbers to chart, in plotting order. Each is
  one point on a line chart, numbered from 1 by its position. The list is
  written into a JavaScript array in the page, and the page shows a table
  of the same numbers beneath the chart. Take the numbers from the person
  or their source; do not make any up.
EOF
cat > templates/page.html.liquid <<'EOF'
{%- comment %}
escape: html is on, so {{ }} text is HTML-escaped. The numbers go into a
JavaScript array through json_script, which can never close the <script>.
{% endcomment -%}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{{ inputs.data.title }}</title>
<style>
:root {
  color-scheme: light dark;
  --surface: #fcfcfb; --ink: #0b0b0b; --ink-2: #52514e;
  --grid: #e6e5e1; --series: #2a78d6;
}
@media (prefers-color-scheme: dark) {
  :root { --surface: #1a1a19; --ink: #f0efec; --ink-2: #c3c2b7; --grid: #383835; --series: #3987e5; }
}
body { margin: 0; padding: 24px; background: var(--surface); color: var(--ink); font: 14px/1.4 system-ui, sans-serif; }
main { max-width: 860px; margin: 0 auto; }
h1 { font-size: 20px; font-weight: 600; margin: 0 0 4px; }
.sub { color: var(--ink-2); margin: 0 0 16px; }
#chart { position: relative; }
svg { display: block; width: 100%; height: auto; overflow: visible; }
svg text { fill: var(--ink-2); font-size: 12px; }
.grid { stroke: var(--grid); stroke-width: 1; }
.line { fill: none; stroke: var(--series); stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
.dot { fill: var(--series); stroke: var(--surface); stroke-width: 2; }
.cross { stroke: var(--ink-2); stroke-width: 1; stroke-dasharray: 3 3; }
#tip { position: absolute; pointer-events: none; padding: 6px 10px; border-radius: 6px; background: var(--surface);
  border: 1px solid var(--grid); box-shadow: 0 2px 8px rgba(0,0,0,.15); white-space: nowrap; display: none; }
#tip b { font-variant-numeric: tabular-nums; }
details { margin-top: 16px; }
summary { cursor: pointer; color: var(--ink-2); }
table { border-collapse: collapse; margin-top: 8px; font-variant-numeric: tabular-nums; }
th, td { text-align: right; padding: 2px 14px; border-bottom: 1px solid var(--grid); }
</style>
</head>
<body>
<main>
<h1>{{ inputs.data.title }}</h1>
<p class="sub" id="sub"></p>
<div id="chart"><div id="tip" role="status"></div></div>
<details>
  <summary>Table of values</summary>
  <table><thead><tr><th>#</th><th>{% if inputs.data.unit %}{{ inputs.data.unit }}{% else %}Value{% endif %}</th></tr></thead><tbody id="rows"></tbody></table>
</details>
</main>
<script>
const values = {{ inputs.data.values | json_script }};
const unit = {{ inputs.data.unit | default: "" | json_script }};
(function () {
  const NS = "http://www.w3.org/2000/svg";
  const W = 860, H = 340, m = { t: 12, r: 16, b: 28, l: 52 };
  const iw = W - m.l - m.r, ih = H - m.t - m.b;
  const fmt = n => Number(n.toPrecision(6)).toLocaleString();
  const n = values.length;
  let lo = Math.min(...values), hi = Math.max(...values);
  if (lo > 0) lo = 0;            // bar-like baseline for all-positive data
  if (hi < 0) hi = 0;
  if (lo === hi) hi = lo + 1;
  const step = Math.pow(10, Math.floor(Math.log10((hi - lo) / 4)));
  const inc = [1, 2, 5, 10].map(k => k * step).find(s => (hi - lo) / s <= 5);
  lo = Math.floor(lo / inc) * inc; hi = Math.ceil(hi / inc) * inc;
  const x = i => m.l + (n === 1 ? iw / 2 : i * iw / (n - 1));
  const y = v => m.t + ih - (v - lo) / (hi - lo) * ih;
  const el = (tag, attrs, parent) => {
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  };
  const svg = el("svg", { viewBox: `0 0 ${W} ${H}`, role: "img",
    "aria-label": `Line chart of ${n} values from ${fmt(Math.min(...values))} to ${fmt(Math.max(...values))}` });
  for (let t = lo; t <= hi + inc / 1e6; t += inc) {
    el("line", { class: "grid", x1: m.l, x2: W - m.r, y1: y(t), y2: y(t) }, svg);
    el("text", { x: m.l - 8, y: y(t) + 4, "text-anchor": "end" }, svg).textContent = fmt(t);
  }
  const every = Math.max(1, Math.ceil(n / 12));
  for (let i = 0; i < n; i += every)
    el("text", { x: x(i), y: H - 8, "text-anchor": "middle" }, svg).textContent = i + 1;
  el("path", { class: "line", d: values.map((v, i) => (i ? "L" : "M") + x(i) + " " + y(v)).join("") }, svg);
  if (n <= 60) values.forEach((v, i) => el("circle", { class: "dot", cx: x(i), cy: y(v), r: 4 }, svg));
  const cross = el("line", { class: "cross", y1: m.t, y2: m.t + ih, visibility: "hidden" }, svg);
  const mark = el("circle", { class: "dot", r: 5, visibility: "hidden" }, svg);
  const box = document.getElementById("chart"), tip = document.getElementById("tip");
  box.insertBefore(svg, tip);
  svg.addEventListener("mousemove", e => {
    const r = svg.getBoundingClientRect(), px = (e.clientX - r.left) * W / r.width;
    const i = Math.max(0, Math.min(n - 1, Math.round(n === 1 ? 0 : (px - m.l) / iw * (n - 1))));
    cross.setAttribute("x1", x(i)); cross.setAttribute("x2", x(i)); cross.setAttribute("visibility", "visible");
    mark.setAttribute("cx", x(i)); mark.setAttribute("cy", y(values[i])); mark.setAttribute("visibility", "visible");
    tip.innerHTML = `#${i + 1}: <b></b>`;
    tip.querySelector("b").textContent = fmt(values[i]) + (unit ? " " + unit : "");
    tip.style.display = "block";
    const left = x(i) * r.width / W;
    tip.style.left = Math.min(left + 12, r.width - tip.offsetWidth) + "px";
    tip.style.top = Math.max(0, y(values[i]) * r.height / H - 36) + "px";
  });
  svg.addEventListener("mouseleave", () => {
    cross.setAttribute("visibility", "hidden"); mark.setAttribute("visibility", "hidden"); tip.style.display = "none";
  });
  document.getElementById("sub").textContent =
    `${n} value${n === 1 ? "" : "s"}, min ${fmt(Math.min(...values))}, max ${fmt(Math.max(...values))}` + (unit ? ` (${unit})` : "");
  const rows = document.getElementById("rows");
  values.forEach((v, i) => {
    const tr = rows.insertRow();
    tr.insertCell().textContent = i + 1;
    tr.insertCell().textContent = fmt(v);
  });
})();
</script>
</body>
</html>
EOF
metais check . && metais render . --sample --out /ux/host && grep -n "const values\|const unit" /ux/host*.html

