    `${n} value${n === 1 ? "" : "s"}, min ${fmt(Math.min(...values))}, max ${fmt(Math.max(...values))}` + (unit ? ` (${unit})` : "");
  const rows = document.getElementById("rows");
  values.forEach((v, i) => {
    const tr = rows.insertRow();
    tr.insertCell().textContent = i + 1;
    tr.insertCell().textContent = fmt(v);
  });
})();
</script>
</body>
</html>
